let step = 1;
let animFrame = null;
let particles = [];

let pState = null; // { x, y, vx, vy, radius, hp, maxHp, data, hitTimer, flashTimer }
let oState = null;

// ── Build Selection Grid ──
const grid = document.getElementById('pokemon-grid');
POKEMON.forEach((p, i) => {
  const card = document.createElement('div');
  card.className = 'poke-card';
  card.dataset.index = i;
  card.innerHTML = `
    <span class="poke-emoji">${p.emoji}</span>
    <div class="poke-name">${p.name}</div>
    <div class="poke-stats">
      <span class="stat-hp">HP ${p.hp}</span> &nbsp;
      <span class="stat-atk">ATK ${p.attack}</span><br>
      <span class="stat-spd">SPD ${p.speed}</span>
    </div>
  `;
  card.addEventListener('click', () => onCardClick(i, card));
  grid.appendChild(card);
});

function onCardClick(index, card) {
  if (card.classList.contains('disabled')) return;

  if (step === 1) {
    // Clear previous player selection
    document.querySelectorAll('.poke-card').forEach(c => c.classList.remove('selected-player'));
    selectedPlayer = index;
    card.classList.add('selected-player');
    step = 2;
    document.getElementById('step-label').textContent = 'Step 2: Choose your OPPONENT';
    // Disable the selected card for opponent step
    updateCardStates();
  } else if (step === 2) {
    if (index === selectedPlayer) return;
    document.querySelectorAll('.poke-card').forEach(c => c.classList.remove('selected-opponent'));
    selectedOpponent = index;
    card.classList.add('selected-opponent');
    updateCardStates();
    const btn = document.getElementById('start-btn');
    btn.classList.add('ready');
  }
}

function updateCardStates() {
  document.querySelectorAll('.poke-card').forEach((c, i) => {
    c.classList.remove('disabled');
    if (step === 2 && i === selectedPlayer) c.classList.add('disabled');
  });
}

document.getElementById('start-btn').addEventListener('click', () => {
  if (selectedPlayer === null || selectedOpponent === null) return;
  startBattle();
});

