173	  #gameover-title.lose { color: #ef5350; }
174	  #gameover-emoji { font-size: 5rem; margin: 16px 0; display: block; }
175	  #gameover-msg { font-size: 1.1rem; color: #ccc; margin-bottom: 30px; }
176	  #play-again-btn {
177	    padding: 14px 50px;
178	    font-size: 1.1rem;
179	    font-weight: 700;
180	    background: linear-gradient(135deg, #f5c542, #f39c12);
181	    color: #1a1a2e;
182	    border: none;
183	    border-radius: 30px;
184	    cursor: pointer;
185	    transition: transform 0.15s;
186	    box-shadow: 0 4px 20px #f5c54260;
187	  }
188	  #play-again-btn:hover { transform: scale(1.05); }
189	</style>
190	</head>
191	<body>
192	
193	<!-- Selection Screen -->
194	<div id="screen-select" class="screen active">
195	  <h1>⚡ Pokemon Arena ⚡</h1>
196	  <p class="step-label" id="step-label">Step 1: Choose YOUR Pokemon</p>
197	  <div class="pokemon-grid" id="pokemon-grid"></div>
198	  <button id="start-btn">Start Battle!</button>
199	</div>
200	
201	<!-- Battle Screen -->
202	<div id="screen-battle" class="screen">
203	  <div class="hud">
204	    <div class="hud-box player">
205	      <div class="hud-name" id="p-name">—</div>
206	      <div class="hp-bar-bg"><div class="hp-bar" id="p-hp-bar" style="width:100%"></div></div>
207	      <div class="hp-text" id="p-hp-text"></div>
208	    </div>
209	    <div class="hud-vs">VS</div>
210	    <div class="hud-box opponent">
211	      <div class="hud-name" id="o-name">—</div>
212	      <div class="hp-bar-bg"><div class="hp-bar" id="o-hp-bar" style="width:100%"></div></div>
213	      <div class="hp-text" id="o-hp-text"></div>
214	    </div>
215	  </div>
216	  <canvas id="arena-canvas" width="700" height="420"></canvas>
217	  <div id="battle-log">Get ready...</div>
218	</div>
219	
220	<!-- Game Over Screen -->
221	<div id="screen-gameover" class="screen">
222	  <div id="gameover-title">YOU WIN!</div>
223	  <span id="gameover-emoji">🏆</span>
224	  <div id="gameover-msg"></div>
225	  <button id="play-again-btn">Play Again</button>
226	</div>
227	
228	<script>
229	const POKEMON = [
230	  { name: "Charizard", emoji: "🔥", hp: 150, attack: 25, speed: 3,   color: "#FF6B35", glow: "#FF6B3560" },
231	  { name: "Pikachu",   emoji: "⚡", hp: 90,  attack: 20, speed: 5,   color: "#FFD700", glow: "#FFD70060" },
232	  { name: "Bulbasaur", emoji: "🌿", hp: 120, attack: 15, speed: 3,   color: "#78C850", glow: "#78C85060" },
233	  { name: "Squirtle",  emoji: "💧", hp: 110, attack: 18, speed: 3.5, color: "#6890F0", glow: "#6890F060" },
234	  { name: "Mewtwo",    emoji: "🔮", hp: 200, attack: 35, speed: 4,   color: "#9B59B6", glow: "#9B59B660" },
235	  { name: "Snorlax",   emoji: "😴", hp: 250, attack: 10, speed: 1.5, color: "#A8A878", glow: "#A8A87860" },
236	  { name: "Gengar",    emoji: "👻", hp: 80,  attack: 40, speed: 4.5, color: "#705898", glow: "#70589860" },
237	  { name: "Eevee",     emoji: "🦊", hp: 100, attack: 15, speed: 4,   color: "#C8A85C", glow: "#C8A85C60" },
238	];
239	
240	const MIN_RADIUS = 28;
241	const MAX_RADIUS = 46;
242	const MAX_HP = Math.max(...POKEMON.map(p => p.hp));
243	
244	function getRadius(hp) {
245	  return MIN_RADIUS + (hp / MAX_HP) * (MAX_RADIUS - MIN_RADIUS);
246	}
247	
248	// ── State ──
249	let selectedPlayer = null;
250	let selectedOpponent = null;
251	let step = 1;
252	let animFrame = null;
253	let particles = [];
254	
255	let pState = null; // { x, y, vx, vy, radius, hp, maxHp, data, hitTimer, flashTimer }
256	let oState = null;
257	
258	// ── Build Selection Grid ──
259	const grid = document.getElementById('pokemon-grid');
260	POKEMON.forEach((p, i) => {
261	  const card = document.createElement('div');
262	  card.className = 'poke-card';
263	  card.dataset.index = i;
264	  card.innerHTML = `
265	    <span class="poke-emoji">${p.emoji}</span>
266	    <div class="poke-name">${p.name}</div>
267	    <div class="poke-stats">
268	      <span class="stat-hp">HP ${p.hp}</span> &nbsp;
269	      <span class="stat-atk">ATK ${p.attack}</span><br>
270	      <span class="stat-spd">SPD ${p.speed}</span>
271	    </div>
272	  `;
273	  card.addEventListener('click', () => onCardClick(i, card));
274	  grid.appendChild(card);
275	});
276	
277	function onCardClick(index, card) {
278	  if (card.classList.contains('disabled')) return;
279	
280	  if (step === 1) {
281	    // Clear previous player selection
282	    document.querySelectorAll('.poke-card').forEach(c => c.classList.remove('selected-player'));
283	    selectedPlayer = index;
284	    card.classList.add('selected-player');
285	    step = 2;
286	    document.getElementById('step-label').textContent = 'Step 2: Choose your OPPONENT';
287	    // Disable the selected card for opponent step
288	    updateCardStates();
289	  } else if (step === 2) {
290	    if (index === selectedPlayer) return;
291	    document.querySelectorAll('.poke-card').forEach(c => c.classList.remove('selected-opponent'));
292	    selectedOpponent = index;
293	    card.classList.add('selected-opponent');
294	    updateCardStates();
295	    const btn = document.getElementById('start-btn');
296	    btn.classList.add('ready');
297	  }
298	}
299	
300	function updateCardStates() {
301	  document.querySelectorAll('.poke-card').forEach((c, i) => {
302	    c.classList.remove('disabled');
303	    if (step === 2 && i === selectedPlayer) c.classList.add('disabled');
304	  });
305	}
306	
307	document.getElementById('start-btn').addEventListener('click', () => {
308	  if (selectedPlayer === null || selectedOpponent === null) return;
309	  startBattle();
310	});
311	
312	document.getElementById('play-again-btn').addEventListener('click', resetToSelect);
313	
314	// ── Battle ──
315	const canvas = document.getElementById('arena-canvas');
316	const ctx = canvas.getContext('2d');
317	const W = canvas.width;
318	const H = canvas.height;
319	
320	function startBattle() {
321	  showScreen('battle');
322	
323	  const pd = POKEMON[selectedPlayer];
324	  const od = POKEMON[selectedOpponent];
325	
326	  const pr = getRadius(pd.hp);
327	  const or = getRadius(od.hp);
328	
329	  pState = {
330	    x: pr + 20, y: H / 2,
331	    vx: pd.speed * (Math.random() > 0.5 ? 1 : -1),
332	    vy: pd.speed * (Math.random() > 0.5 ? 0.6 : -0.6),
333	    radius: pr,
334	    hp: pd.hp, maxHp: pd.hp,
335	    data: pd,
336	    hitTimer: 0, flashTimer: 0
337	  };
338	
339	  oState = {
340	    x: W - or - 20, y: H / 2,
341	    vx: -od.speed * (Math.random() > 0.5 ? 1 : -1),
342	    vy: od.speed * (Math.random() > 0.5 ? 0.6 : -0.6),
343	    radius: or,
344	    hp: od.hp, maxHp: od.hp,
345	    data: od,
346	    hitTimer: 0, flashTimer: 0
347	  };
348	
349	  particles = [];
350	
351	  document.getElementById('p-name').textContent = pd.emoji + ' ' + pd.name;
352	  document.getElementById('o-name').textContent = od.emoji + ' ' + od.name;
353	  document.getElementById('battle-log').textContent = 'Battle Start!';
354	
355	  updateHUD();
356	  if (animFrame) cancelAnimationFrame(animFrame);
357	  gameLoop();
358	}
359	
360	function gameLoop() {
361	  update();
362	  render();
363	  if (pState.hp > 0 && oState.hp > 0) {
364	    animFrame = requestAnimationFrame(gameLoop);
365	  } else {
366	    render();
367	    setTimeout(showGameOver, 800);
368	  }
369	}
370	
371	const COLLISION_COOLDOWN = 500; // ms
372	let lastCollisionTime = 0;
373	
374	function update() {
375	  const now = performance.now();
376	
377	  // Move
378	  pState.x += pState.vx;
379	  pState.y += pState.vy;
380	  oState.x += oState.vx;
381	  oState.y += oState.vy;
382	
383	  // Wall bounce — player
384	  wallBounce(pState);
385	  wallBounce(oState);
386	
387	  // Timers
388	  if (pState.hitTimer > 0) pState.hitTimer--;
389	  if (oState.hitTimer > 0) oState.hitTimer--;
390	  if (pState.flashTimer > 0) pState.flashTimer--;
391	  if (oState.flashTimer > 0) oState.flashTimer--;
392	
393	  // Collision check
394	  const dx = pState.x - oState.x;
395	  const dy = pState.y - oState.y;
396	  const dist = Math.sqrt(dx * dx + dy * dy);
397	  const minDist = pState.radius + oState.radius;
398	
399	  if (dist < minDist) {
400	    // Push apart
401	    const overlap = minDist - dist;
402	    const nx = dx / dist;
403	    const ny = dy / dist;
404	    pState.x += nx * overlap * 0.5;
405	    pState.y += ny * overlap * 0.5;
406	    oState.x -= nx * overlap * 0.5;
407	    oState.y -= ny * overlap * 0.5;
408	
409	    // Elastic bounce
410	    const dvx = pState.vx - oState.vx;
411	    const dvy = pState.vy - oState.vy;
412	    const dot = dvx * nx + dvy * ny;
413	    if (dot < 0) {
414	      pState.vx -= dot * nx;
415	      pState.vy -= dot * ny;
416	      oState.vx += dot * nx;
417	      oState.vy += dot * ny;
418	    }
419	
420	    // Deal damage with cooldown
421	    if (now - lastCollisionTime > COLLISION_COOLDOWN) {
422	      lastCollisionTime = now;
423	      const pDmg = oState.data.attack;
424	      const oDmg = pState.data.attack;
425	      pState.hp = Math.max(0, pState.hp - pDmg);
426	      oState.hp = Math.max(0, oState.hp - oDmg);
427	      pState.flashTimer = 12;
428	      oState.flashTimer = 12;
429	
430	      const midX = (pState.x + oState.x) / 2;
431	      const midY = (pState.y + oState.y) / 2;
432	      spawnParticle(pState.x, pState.y - pState.radius, `-${pDmg}`, '#ef5350');
433	      spawnParticle(oState.x, oState.y - oState.radius, `-${oDmg}`, '#4fc3f7');
434	
435	      document.getElementById('battle-log').textContent =
436	        `${pState.data.name} took ${pDmg} dmg! ${oState.data.name} took ${oDmg} dmg!`;
437	      updateHUD();
438	    }
439	  }
440	
441	  // Update particles
442	  particles = particles.filter(p => p.life > 0);
443	  particles.forEach(p => {
444	    p.y -= 1.2;
445	    p.life--;
446	    p.alpha = p.life / p.maxLife;
447	  });
448	}
449	
450	function wallBounce(s) {
451	  if (s.x - s.radius < 0) { s.x = s.radius; s.vx = Math.abs(s.vx); }
452	  if (s.x + s.radius > W) { s.x = W - s.radius; s.vx = -Math.abs(s.vx); }
453	  if (s.y - s.radius < 0) { s.y = s.radius; s.vy = Math.abs(s.vy); }
454	  if (s.y + s.radius > H) { s.y = H - s.radius; s.vy = -Math.abs(s.vy); }
455	}
456	
457	function spawnParticle(x, y, text, color) {
458	  particles.push({ x, y, text, color, life: 50, maxLife: 50, alpha: 1 });
459	}
460	
461	function render() {
462	  // Background
463	  ctx.fillStyle = '#0f2e1a';
464	  ctx.fillRect(0, 0, W, H);
465	
466	  // Grass grid pattern
467	  ctx.strokeStyle = '#1a4a2a';
468	  ctx.lineWidth = 1;
469	  for (let x = 0; x < W; x += 40) {
470	    ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H); ctx.stroke();
471	  }
472	  for (let y = 0; y < H; y += 40) {
473	    ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
474	  }
475	
476	  // Center circle
477	  ctx.beginPath();
478	  ctx.arc(W / 2, H / 2, 80, 0, Math.PI * 2);
479	  ctx.strokeStyle = '#1e5c30';
480	  ctx.lineWidth = 2;
481	  ctx.stroke();
482	  ctx.beginPath();
483	  ctx.moveTo(W / 2, 0); ctx.lineTo(W / 2, H);
484	  ctx.strokeStyle = '#1e5c30';
485	  ctx.stroke();
486	
487	  drawPokemon(pState, '#4fc3f7');
488	  drawPokemon(oState, '#ef5350');
489	
490	  // Particles
491	  particles.forEach(p => {
492	    ctx.save();
493	    ctx.globalAlpha = p.alpha;
494	    ctx.font = 'bold 16px Segoe UI';
495	    ctx.fillStyle = p.color;
496	    ctx.shadowColor = p.color;
497	    ctx.shadowBlur = 8;
498	    ctx.fillText(p.text, p.x - 10, p.y);
499	    ctx.restore();
500	  });
501	}
502	
503	function drawPokemon(s, ringColor) {
504	  ctx.save();
505	
506	  const isFlashing = s.flashTimer > 0 && Math.floor(s.flashTimer / 3) % 2 === 0;
507	
508	  // Glow
509	  ctx.shadowColor = s.data.glow;
510	  ctx.shadowBlur = 20;
511	
512	  // Circle
513	  ctx.beginPath();
514	  ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
515	  if (isFlashing) {
516	    ctx.fillStyle = '#ffffff88';
517	  } else {
518	    ctx.fillStyle = s.data.color + 'cc';
519	  }
520	  ctx.fill();
521	
522	  // Ring
523	  ctx.lineWidth = 3;
524	  ctx.strokeStyle = isFlashing ? '#ffffff' : ringColor;
525	  ctx.stroke();
526	
527	  ctx.shadowBlur = 0;
528	
529	  // Emoji
530	  const fontSize = s.radius * 0.9;
531	  ctx.font = `${fontSize}px serif`;
532	  ctx.textAlign = 'center';
533	  ctx.textBaseline = 'middle';
534	  ctx.fillText(s.data.emoji, s.x, s.y);
535	
536	  // Name label
537	  ctx.font = 'bold 11px Segoe UI';
538	  ctx.textBaseline = 'top';
539	  ctx.fillStyle = '#fff';
540	  ctx.shadowColor = '#000';
541	  ctx.shadowBlur = 4;
542	  ctx.fillText(s.data.name, s.x, s.y + s.radius + 4);
543	
544	  ctx.restore();
545	}
546	
547	function updateHUD() {
548	  const pPct = Math.max(0, pState.hp / pState.maxHp * 100);
549	  const oPct = Math.max(0, oState.hp / oState.maxHp * 100);
550	  document.getElementById('p-hp-bar').style.width = pPct + '%';
551	  document.getElementById('o-hp-bar').style.width = oPct + '%';
552	  document.getElementById('p-hp-text').textContent = `${pState.hp} / ${pState.maxHp} HP`;
553	  document.getElementById('o-hp-text').textContent = `${oState.hp} / ${oState.maxHp} HP`;
554	
555	  // Color shift when low HP
556	  const pBar = document.getElementById('p-hp-bar');
557	  const oBar = document.getElementById('o-hp-bar');
558	  pBar.style.background = pPct < 25 ? '#ef5350' : pPct < 50 ? '#ffa726' : '#4fc3f7';
559	  oBar.style.background = oPct < 25 ? '#ffd54f' : oPct < 50 ? '#ffa726' : '#ef5350';
560	}
561	
562	function showGameOver() {
563	  const playerWon = pState.hp > 0 && oState.hp <= 0;
564	  const draw = pState.hp <= 0 && oState.hp <= 0;
565	
566	  const title = document.getElementById('gameover-title');
567	  const emoji = document.getElementById('gameover-emoji');
568	  const msg = document.getElementById('gameover-msg');
569	
570	  if (draw) {
571	    title.textContent = 'DRAW!';
572	    title.className = '';
573	    title.style.color = '#f5c542';
574	    emoji.textContent = '🤝';
575	    msg.textContent = 'Both Pokemon fainted at the same time!';
576	  } else if (playerWon) {
577	    title.textContent = 'YOU WIN!';
578	    title.className = 'win';
579	    emoji.textContent = pState.data.emoji + '🏆';
580	    msg.textContent = `${pState.data.name} defeated ${oState.data.name}!`;
581	  } else {
582	    title.textContent = 'YOU LOSE!';
583	    title.className = 'lose';
584	    emoji.textContent = '💀';
585	    msg.textContent = `${oState.data.name} defeated ${pState.data.name}!`;
586	  }
587	
588	  showScreen('gameover');
589	}
590	
591	function resetToSelect() {
592	  selectedPlayer = null;
593	  selectedOpponent = null;
594	  step = 1;
595	  if (animFrame) { cancelAnimationFrame(animFrame); animFrame = null; }
596	  document.querySelectorAll('.poke-card').forEach(c => {
597	    c.classList.remove('selected-player', 'selected-opponent', 'disabled');
598	  });
599	  document.getElementById('step-label').textContent = 'Step 1: Choose YOUR Pokemon';
600	  document.getElementById('start-btn').classList.remove('ready');
601	  showScreen('select');
602	}
603	
604	function showScreen(name) {
605	  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
606	  document.getElementById('screen-' + name).classList.add('active');
607	}
608	</script>
